"""Build a dated, additive research supplement. Frozen ledgers remain unchanged."""
from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parents[1]
d=json.loads((ROOT.parent/'municipal-mobility-history/data/research-updates.json').read_text())
e=lambda s:html.escape(str(s),quote=True)
def sources(rows):
 return '<ol class="sources">'+''.join(f'<li><a href="{e(s["url"])}" target="_blank" rel="noopener noreferrer">{e(s["title"])} ↗</a><span>{e(s["document_date"])} ／ {e(s["locator"])}</span></li>' for s in rows)+'</ol>'
cards=[]
for cid,c in d['cases'].items():
 cards.append(f'<article id="{e(c["slug"])}" class="case"><p class="eyebrow">地域の経過 · 原典再照合</p><h2>{e(c["title"])}</h2><p class="lede">{e(c["current_observation"])}</p><p class="date">根拠時点 {e(c["evidence_as_of"])}</p><ul class="findings">'+''.join('<li>'+e(s)+'</li>' for s in c['findings'])+'</ul>'+sources(c['sources'])+f'<a class="button" href="../../../municipal-mobility-history/#case/{cid}">この取組の全履歴を見る ↗</a></article>')
timeline=''.join(f'<li><time>{e(x["date"])}</time><div><h3>{e(x["title"])}</h3><p>{e(x["text"])}</p><a href="{e(d["policy_sources"][x["source"]]["url"])}" target="_blank" rel="noopener noreferrer">原典 {e(x["locator"])} ↗</a></div></li>' for x in d['policy_events'])
css='''*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:24px}body{margin:0;background:#091018;color:#f3f7f7;font-family:Arial,"Noto Sans JP","Hiragino Kaku Gothic ProN",Meiryo,sans-serif;line-height:1.85}a{color:#80e5da;text-underline-offset:.3em}a:hover{color:#fff}a:focus-visible{outline:3px solid #ffc96d;outline-offset:5px}.wrap{width:min(1100px,calc(100% - 48px));margin:auto}header{display:flex;justify-content:space-between;align-items:center;gap:22px;padding:26px 0;border-bottom:1px solid #35434d}header a{text-decoration:none;font-weight:800}.brand{font-size:15px;line-height:1.15;color:#fff}.hero{padding:80px 0 48px}.eyebrow{font:700 12px/1.5 Arial,sans-serif;letter-spacing:.15em;color:#80e5da}h1,h2,h3{font-weight:900;line-height:1.3;letter-spacing:-.04em;margin:18px 0}h1{font-size:clamp(40px,6.4vw,76px)}h1 span{color:#80e5da}h1 .keep{white-space:nowrap;color:inherit}h2{font-size:clamp(27px,3.5vw,43px)}h3{font-size:clamp(20px,2.3vw,27px)}p{max-width:80ch}.lede{font-size:clamp(17px,2vw,21px);font-weight:600}.date,.muted{color:#b7c4ce;font-size:14px}.nav{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin:30px 0 50px}.nav a{background:#15232d;padding:18px 12px;text-decoration:none;font-size:14px;font-weight:800;border-top:3px solid #80e5da}.nav a:nth-child(2n){border-color:#ffc96d}.case,section.policy{padding:48px 0;border-top:1px solid #35434d;scroll-margin-top:24px}.findings{padding-left:1.3em;max-width:88ch}.findings li{margin:15px 0}.sources{background:#101d27;padding:20px 24px 20px 45px;font-size:14px}.sources li{margin:13px 0;overflow-wrap:anywhere}.sources span{display:block;color:#b7c4ce;font-size:12px}.button{display:inline-block;padding:12px 0;font-weight:800}.comparison{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:30px 0}.comparison article{padding:22px;background:#13212b;border-top:4px solid #80e5da}.comparison article:nth-child(2){border-color:#ffc96d}.large{display:block;font-size:clamp(30px,4.6vw,52px);line-height:1.2;font-weight:900;margin:18px 0}.tag{color:#ffc96d;font-weight:700}.timeline{list-style:none;padding:0}.timeline>li{display:grid;grid-template-columns:150px 1fr;gap:25px;border-top:1px solid #35434d;padding:25px 0}.timeline time{font-size:21px;color:#ffc96d;font-weight:900}.timeline h3{margin:0}.notice{padding:22px;border-left:4px solid #ffc96d;background:#201f1b}.next{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.next a{display:block;background:#13212b;padding:20px;text-decoration:none}.next b{display:block;font-size:23px;color:#fff}.next small{display:block;color:#b7c4ce;font-size:13px;margin-top:8px}footer{margin:55px 0 25px;border-top:1px solid #35434d;padding-top:25px;font-size:13px}.skip{position:absolute;top:-80px;left:20px;background:#fff;color:#000;padding:10px}.skip:focus{top:10px}@media(max-width:650px){.wrap{width:calc(100% - 32px)}header{align-items:flex-start;font-size:12px}.hero{padding-top:45px}.nav{grid-template-columns:repeat(2,1fr)}.nav a:last-child{grid-column:1/-1}.comparison,.next{grid-template-columns:1fr}.timeline>li{grid-template-columns:1fr;gap:7px}.sources{padding:16px 16px 16px 35px}.case,section.policy{padding:32px 0}h1{font-size:clamp(34px,10vw,56px)}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}'''
page=f'''<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#091018"><title>原典で追う、その後のモビリティ｜2026年11月追補｜MDL</title><meta name="description" content="日立のL4休止、GunMaaSの展開と移行予定、小松の運行方式、永平寺の選定日を照合。公共・日本版ライドシェアの制度変遷を一次資料からたどる。"><link rel="canonical" href="https://mobilitydlab.com/mobility-policy-history/updates/2026-11/"><style>{css}</style></head><body><a class="skip" href="#main">本文へ</a><div class="wrap"><header><a class="brand" href="../../../">MOBILITY<br>DESIGN LAB.</a><a href="../../">政策史へ戻る ↗</a></header><main id="main"><div class="hero"><p class="eyebrow">RESEARCH UPDATE / 2026.11.03</p><h1>始まった、<wbr><span class="keep">その後を。</span><br><span>原典で追い直す。</span></h1><p class="lede">継続、休止、方式変更、次の計画。<br>新しい資料が、過去の読み方を更新する。</p><p class="muted">追加調査の原典確認日：2026年11月3日。各資料の公表日・観測期間・予定日を区別して掲載。</p><nav class="nav" aria-label="追補の内容"><a href="#hitachi">日立 · L4休止 ↓</a><a href="#gunma">GunMaaS · 展開 ↓</a><a href="#komatsu">小松 · 手動運転 ↓</a><a href="#eiheiji">永平寺 · 日付照合 ↓</a><a href="#rideshare">ライドシェア · 制度史 ↓</a></nav><p class="notice">{e(d['scope'])} 補助事業の採択、サービス開始、実証終了、運行休止は、それぞれ別の事実として読む。</p></div>{''.join(cards)}<section id="rideshare" class="policy"><p class="eyebrow">POLICY HISTORY / TWO LEGAL FRAMEWORKS</p><h2>同じ「ライドシェア」でも、<br>制度の入口が違う。</h2><p>公共ライドシェアと日本版ライドシェアを分けてから、地域で何が実現したかを確かめる。オンデマンドは運行方式であり、これらの制度名と同義ではない。</p><div class="comparison"><article><p class="tag">公共ライドシェア</p><strong class="large">78条2号</strong><h3>自家用有償旅客運送</h3><p>自治体・NPO等が担う仕組み。道路運送法79条の登録制度に基づく。交通空白地有償運送と福祉有償運送を含む。</p></article><article><p class="tag">日本版ライドシェア</p><strong class="large">78条3号</strong><h3>自家用車活用事業</h3><p>タクシー事業者の管理下で、地域・時間帯のタクシー不足を補う仕組み。登録とは異なる許可の取扱い。</p></article></div><p class="date">制度の比較は国交省2025年6月資料PDF17頁、登録制度は2006年制度改正説明、許可は2024年3月29日の通達に基づく。現在の個別の許可条件を判断するための案内ではありません。</p><ol class="timeline">{timeline}</ol><p class="notice">「14件の事務連絡を廃止」は「ライドシェア制度が終了」とは違う。制度の変更は、地域の採択件数や運行実績にもそのまま置き換えない。</p>{sources(d['policy_sources'])}<h3>制度と、地域の記録を行き来する。</h3><div class="next"><a href="../../../municipal-mobility-history/#case/P-b7090e6aa5551573"><b>中頓別町 ↗</b><small>2016年からの実証と事業化。「ライドシェア」という名称だけで法的区分を決めない。</small></a><a href="../../../municipal-mobility-history/#case/P-351fc0640a9658cb"><b>三田市・藍 ↗</b><small>道路運送法78条2号の記録。公共ライドシェアと定時定路線の組み合わせを読む。</small></a><a href="../../../municipal-mobility-history/#case/P-aed5a36b2dacf146"><b>村上市・山北 ↗</b><small>病院車両を活用する定時定路線。実証期間と途中までの実績を分ける。</small></a></div></section><section class="policy"><p class="eyebrow">WHAT REMAINS OPEN</p><h2>確認できないことも、残す。</h2><ul class="findings"><li>日立のL4営業運行の再開日、小松の自動運転モード復帰は、今回確認した資料では未確認。</li><li>GunMaaSのSuica移行は2027年3月の予定。将来の実装・利用成果・確定費用は、後続資料で確認する。</li><li>制度緩和と利用増の因果関係は、ここに挙げた公表資料だけでは評価しない。補助の採択・支援額と、結果・決算も別に扱う。</li></ul><a class="button" href="../../">政策と地域のアーカイブへ戻る ↗</a></section></main><footer><p>MDL RESEARCH ARCHIVE · 原典確認 2026.11.03</p><p>既存のPDF・Excel・基礎集計は作成時点の記録。今回の追補はこのページと各事例の追加確認欄で参照できます。</p></footer></div></body></html>'''
out=ROOT/'updates/2026-11/index.html';out.parent.mkdir(parents=True,exist_ok=True);out.write_text(page)
print(out.relative_to(ROOT.parent))
